const fs = require('fs');
const rows = fs.readFileSync('data.csv', 'utf8').trim().split(/\r?\n/).slice(1);
let sum = 0;
for (const r of rows) {
  const v = Number(r.split(',')[1]);
  if (!Number.isNaN(v)) sum += v;
}
console.log(sum);
```
